      "@type": "Question",
      "name": "What's the difference between a word counter and a keyword density checker?",
      "acceptedAnswer": { "@type": "Answer", "text": "A word counter only reports total word count. A keyword density checker uses that same total as the denominator in its calculation, then adds the extra step of counting how often specific phrases appear within it." }
